mapper.select:
select t.modal_json,t.modal_json modalJson,t.scene_name,t.scene_name sceneName,t.scene_id,t.scene_id
sceneId,t.status_cd,t.status_cd statusCd,t.state,t.community_id,t.community_id communityId,t.seq
from dt_scene t
where 1 =1

    and t.modal_json= #{modalJson}


    and t.scene_name= #{sceneName}


    and t.scene_id= #{sceneId}


    and t.status_cd= #{statusCd}


    and t.state= #{state}


    and t.community_id= #{communityId}


    and t.seq= #{seq}

order by t.create_time desc

    limit #{page}, #{row}

